<template><section class="dm-settings-panel"><label><span>私信权限</span><select v-model="permission"><option v-for="option in options" :key="option.value" :value="option.value">{{ option.label }}</option></select></label><p v-if="error" role="alert">{{ error }}</p><p v-else-if="saved" role="status">已保存</p><PButton :loading="saving" @click="save">保存</PButton></section></template>
<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'; import PButton from '@/components/ui/PButton.vue'; import { getDMChannelSettings, getDMSettings, updateDMChannelSettings, updateDMSettings, type DMPermission } from '@/api/dm'
const props = defineProps<{ subject: { type: 'user'; id: string } | { type: 'channel'; id: string } }>(); const permission = ref<DMPermission>('one_before_reply'); const saving = ref(false); const saved = ref(false); const error = ref(''); let requestGeneration = 0; const options = computed(() => props.subject.type === 'user' ? [{value:'one_before_reply',label:'陌生人仅可发一条'},{value:'following_only',label:'仅我关注的人'},{value:'anyone',label:'允许连续发送'}] : [{value:'one_before_reply',label:'陌生人仅可发一条'},{value:'anyone',label:'允许连续发送'},{value:'closed',label:'关闭频道私信'}]); const load = async () => { const generation = ++requestGeneration; saved.value=false; error.value=''; try { const settings = props.subject.type === 'user' ? await getDMSettings() : await getDMChannelSettings(props.subject.id); if (generation === requestGeneration) permission.value = settings.permission } catch { if (generation === requestGeneration) error.value = '加载失败' } }; const save = async () => { const generation = requestGeneration; saving.value=true;saved.value=false;error.value='';try { const result = props.subject.type === 'user' ? await updateDMSettings({permission:permission.value}) : await updateDMChannelSettings(props.subject.id,{permission:permission.value}); if (generation === requestGeneration) { permission.value=result.permission;saved.value=true } } catch { if (generation === requestGeneration) error.value='保存失败' } finally { if (generation === requestGeneration) saving.value=false } }; onMounted(load); watch(() => `${props.subject.type}:${props.subject.id}`, load)
</script>
<style scoped>.dm-settings-panel{display:flex;align-items:end;gap:1rem;flex-wrap:wrap}.dm-settings-panel label{display:grid;gap:.4rem}.dm-settings-panel select{min-height:2.5rem;padding:0 .6rem;border:1px solid var(--a-color-border-soft);background:var(--a-color-bg);color:var(--a-color-text);font:inherit}.dm-settings-panel p{margin:0;color:var(--a-color-muted)}</style>
